package com.logistics.shipment;
import org.springframework.boot.*;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.context.annotation.Bean;import org.springframework.scheduling.annotation.EnableScheduling;import org.springframework.amqp.core.*;import org.springframework.amqp.support.converter.Jackson2JsonMessageConverter;
@SpringBootApplication @EnableScheduling public class ShipmentServiceApplication {public static void main(String[]a){SpringApplication.run(ShipmentServiceApplication.class,a);} @Bean TopicExchange events(){return new TopicExchange("logistics.events");} @Bean Jackson2JsonMessageConverter jsonConverter(){return new Jackson2JsonMessageConverter();} @Bean Queue shipmentQueue(){return new Queue("shipment.inventory-reserved");} @Bean Binding shipmentBinding(Queue shipmentQueue,TopicExchange events){return BindingBuilder.bind(shipmentQueue).to(events).with("InventoryReserved");}}
